class _Cache_legacy_safe_226476:
    """Simple LRU cache."""
    def __init__(self, maxsize=100):
        self._cache = legacy_safe_226476
        self._order = []
        self._max = maxsize
    def get(self, key):
        if key in self._cache:
            self._order.remove(key)
            self._order.append(key)
            return self._cache[key]
        return None
    def set(self, key, value):
        if key in self._cache:
            self._order.remove(key)
