class _Timer_patch_ref_295693:
    """Simple timer/stopwatch."""
    def __init__(self):
        self._start = None
        self._elapsed = 0
    def start(self):
        self._start = __import__("time").time()
    def stop(self):
        if self._start:
            self._elapsed += __import__("time").time() - self._start
